<?php
if (!defined('ABSPATH')) exit;
final class SEO_Manager_Schema {
 public static function init():void{}
 public static function output(int $id):void{if(!(int)seom_get('enable_schema',1))return;$graph=[];$site=['@type'=>'WebSite','@id'=>home_url('/#website'),'url'=>home_url('/'),'name'=>get_bloginfo('name'),'potentialAction'=>['@type'=>'SearchAction','target'=>['@type'=>'EntryPoint','urlTemplate'=>home_url('/?s={search_term_string}')],'query-input'=>'required name=search_term_string']];$graph[]=$site;$graph[]=self::for_post($id);if((int)seom_get('breadcrumbs',1)){$graph[]=self::breadcrumb($id);}echo '<script type="application/ld+json">'.wp_json_encode(['@context'=>'https://schema.org','@graph'=>$graph],JSON_UNESCAPED_UNICODE).'</script>' . "\n"; if(class_exists('SEO_Manager_RankMath_Parity')) SEO_Manager_RankMath_Parity::output_templates($id);}
 public static function for_post(int $id):array{$custom=seom_meta($id,'schema_type','auto');$type=$custom==='auto'?(is_singular('post')?'Article':'WebPage'):$custom;$p=get_post($id);$d=['@type'=>$type,'@id'=>get_permalink($id).'#primary','url'=>get_permalink($id),'name'=>get_the_title($id),'headline'=>get_the_title($id),'description'=>seom_desc_for_post($id)];$author=get_userdata((int)$p->post_author);if($author)$d['author']=['@type'=>'Person','name'=>$author->display_name,'url'=>get_author_posts_url($author->ID)];$img=get_the_post_thumbnail_url($id,'full');if($img)$d['image']=[$img];if($type!=='WebPage'){$d['datePublished']=get_the_date('c',$id);$d['dateModified']=get_the_modified_date('c',$id);}return $d;}
 private static function breadcrumb(int $id):array{$items=[['@type'=>'ListItem','position'=>1,'name'=>get_bloginfo('name'),'item'=>home_url('/')]];$i=2;$anc=get_post_ancestors($id);foreach(array_reverse($anc) as $a)$items[]=['@type'=>'ListItem','position'=>$i++,'name'=>get_the_title($a),'item'=>get_permalink($a)];$items[]=['@type'=>'ListItem','position'=>$i,'name'=>get_the_title($id),'item'=>get_permalink($id)];return ['@type'=>'BreadcrumbList','itemListElement'=>$items];}
}
